const norm=s=>String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toUpperCase().replace(/[^A-Z0-9]+/g,' ').trim();
function applyExcelPositions(target,force=false){const key=Object.keys(window.LOB_POSITIONS||{}).find(k=>norm(k).replaceAll(' ','')===norm(target.name).replaceAll(' ',''));const layout=key&&window.LOB_POSITIONS[key];if(!layout||(!force&&target.excelLayoutApplied))return;for(const item of layout.items){let station=target.processes[item.index];if(item.name){const exact=target.processes.find(s=>norm(s.name)===norm(item.name));const similar=target.processes.find(s=>{const a=norm(s.name),b=norm(item.name);return Math.min(a.length,b.length)>7&&(a.includes(b)||b.includes(a))});station=exact||similar||station}if(!station)continue;station.x=item.x;station.y=item.y;if(!(+station.time)&&item.time)station.time=item.time}target.sourceSheet=layout.sheet;target.excelLayoutApplied=true;}
function enrichSkills(target){const key=Object.keys(window.LOB_CATALOG||{}).find(k=>norm(k).replaceAll(' ','')===norm(target.name).replaceAll(' ',''));const rows=key&&window.LOB_CATALOG[key];if(!rows)return;for(const station of target.processes){const row=rows.find(r=>norm(r.name)===norm(station.name))||rows.find(r=>{const a=norm(r.name),b=norm(station.name);return Math.min(a.length,b.length)>7&&(a.includes(b)||b.includes(a))});if(row){station.skill25=station.skill25??row.skill25==='V';station.skill40=station.skill40??row.skill40==='V'}station.critical=!!station.critical}}
Object.values(seed.models).forEach(m=>applyExcelPositions(m,true));
Object.values(seed.models).forEach(enrichSkills);
let state=structuredClone(seed),currentKey='s948',selectedId=null,history=[],session={role:'viewer',email:''},saveTimer=null;
const $=id=>document.getElementById(id),canEdit=()=>['owner','editor'].includes(session.role),model=()=>state.models[currentKey];
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
