function stationSkills(s){const values=Array.isArray(s.multiSkills)?s.multiSkills:[...(s.skill25?[25]:[]),...(s.skill40?[40]:[])];return [...new Set(values.map(Number).filter(v=>Number.isInteger(v)&&v>=1&&v<=100))].sort((a,b)=>a-b)}
