async function request(url,options={}){const response=await fetch(url,{headers:{'content-type':'application/json',...(options.headers||{})},...options});const body=await response.json().catch(()=>({}));if(!response.ok)throw new Error(body.error||'Không thể kết nối máy chủ.');return body}
