function applyRole(){document.body.classList.toggle('readonly',!canEdit());$('roleBadge').textContent=session.role==='owner'?'Chủ sở hữu · chỉnh sửa':session.role==='editor'?'Được phép chỉnh sửa':'Chế độ chỉ xem';$('roleBadge').className='role-badge '+(canEdit()?'edit':'view');$('editorsBtn').hidden=session.role!=='owner';$('saveState').innerHTML=canEdit()?'<i></i>Đã đồng bộ':'Chỉ xem công khai';if(!canEdit()&&!session.email&&!document.getElementById('signinBtn'))$('saveState').insertAdjacentHTML('afterend','<a id="signinBtn" class="btn ghost" href="/signin-with-chatgpt?return_to=/" target="_top">Đăng nhập để sửa</a>')}
