  $('jigList').innerHTML=jigs.length?jigs.map((j,i)=>`<div class="jig-row" data-index="${i}" data-jig-id="${esc(j.id||(j.id='legacy-'+i))}"><label>Loại Jig<select class="jig-type">${[['press','Jig Press · V3'],['attach','Jig Attach'],['tool','Tool']].map(([v,t])=>`<option value="${v}" ${jigType(j)===v?'selected':''}>${t}</option>`).join('')}</select></label><label>Tên Jig<input class="jig-name" value="${esc(j.name||'')}" placeholder="Nhập tên Jig"></label><label>Setup (phút)<input class="jig-setup" type="number" min="0" step="0.1" value="${+j.setup||''}" placeholder="Chưa đo"></label><button class="jig-remove" type="button" title="Xóa Jig">×</button></div>`).join(''):'<div class="jig-empty">Nhấn “+ Thêm Jig” để khai báo.</div>';
  $('jigList').querySelectorAll('.jig-remove').forEach(button=>button.onclick=()=>{if(!canEdit())return;snapshot();const draft=readJigRows();draft.splice(+button.closest('.jig-row').dataset.index,1);station.jigs=draft;renderJigs(station);renderCanvas();renderDomainOverview();renderProcessTable();renderStudio();scheduleSave()});
