  const deduped=[],seen=new Set();for(const [blockIndex,block] of blocks.entries()){const ordered=block.items.sort((a,b)=>a.col-b.col);for(const [columnIndex,item] of ordered.entries()){const key=(item.no||'')+'|'+norm(item.name);if(seen.has(key))continue;seen.add(key);deduped.push({...item,block:blockIndex,columnIndex})}}
